const root=document.getElementById('ailab-unified');
const main=root.querySelector('.nl-main'),overlayHost=root.querySelector('.nl-overlay-host'),aiHost=root.querySelector('.nu-ai-host');
const design={accent:'indigo',radius:12};
const media={frame:0,playing:false};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<i data-lucide="${name}" aria-hidden="true"></i>`;
const btn=(label,action,primary=false,attrs='')=>`<button class="nl-button ${primary?'primary':''}" data-action="${action}" ${attrs}>${label}</button>`;
const plain=(label,action,attrs='')=>`<button class="nl-plain" data-action="${action}" ${attrs}>${label}</button>`;
const tag=(label,color='')=>`<span class="nl-tag ${color}">${label}</span>`;
const heading=(title,sub='',actions='')=>`<div class="nl-heading"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${actions}</div>`;
const statusName=s=>({draft:'草稿',running:'执行中',paused:'已暂停',complete:'已完成',failed:'执行失败',cancelled:'已取消'})[s]||s;
const kv=(key,value)=>`<div class="nl-kv"><span>${key}</span><strong>${value}</strong></div>`;
function field(label,key,value,target='trial',type='text',disabled=false){return `<label class="nl-field">${label}<input type="${type}" data-${target}-field="${key}" value="${esc(value)}" ${disabled?'disabled':''}></label>`;}
function select(label,key,value,options,target='trial',disabled=false){return `<label class="nl-field">${label}<select data-${target}-field="${key}" ${disabled?'disabled':''}>${options.map(x=>{const [v,n]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(n)}</option>`;}).join('')}</select></label>`;}
function check(label,key,value,target='trial',disabled=false){return `<label class="nl-check"><input type="checkbox" data-${target}-field="${key}" ${value?'checked':''} ${disabled?'disabled':''}>${label}</label>`;}
function art(label='',variant=false,video=false){return `<div class="nl-art ${variant?'variant':''} ${video?'video':''}"><img src="${demoImage}" alt="浅色石台上的淡紫色香水瓶，生成摄影示意素材">${label?`<span class="nl-art-label">${label}</span>`:''}</div>`;}
function audio(music=false){return `<audio controls preload="metadata" aria-label="${music?'音乐示例试听':'合成语音示例试听'}" src="${music?demoMusic:demoVoice}"></audio>`;}
function waveform(){return `<div class="nl-wave" aria-hidden="true">${[8,12,17,30,42,22,14,32,54,63,46,32,22,40,58,35,18,25,48,64,50,32,15,26,41,54,25,13,19,34,48,58,33,18,24,40,27,16,8].map(n=>`<span style="height:${n}px"></span>`).join('')}</div>`;}
function trialHistory(){return history().filter(x=>store.kind!=='audio'||x.op===draft().op);}
function trialResult(){return trialHistory().find(x=>x.id===draft().selected)||trialHistory()[0]||null;}
function trialHeader(){const list=store.module==='language'?[['text','对话'],['vision','多模态理解']]:[[store.module,kinds[store.module]]];return `<div class="nu-panel-heading"><h2>运行 / 试用</h2><small>输入与结果在本页持续保留</small></div>${list.length>1?`<div class="nl-tabs" role="tablist" aria-label="运行类型">${list.map(([k,n])=>`<button role="tab" id="nl-kind-${k}" aria-controls="nl-trial-panel" aria-selected="${store.kind===k}" data-kind="${k}">${n}</button>`).join('')}</div>`:`<span id="nl-kind-${store.kind}" class="nu-sr">${kinds[store.kind]}</span>`}`;}

function referenceInput(d){const needed=d.kind==='vision'||d.kind==='video'&&d.mode==='i2v'||d.kind==='image'&&d.mode!=='t2i'||d.kind==='audio'&&['asr','vc'].includes(d.op);if(!needed)return '';return `<div class="nl-reference">${d.reference&&d.kind!=='audio'?`<img src="${demoImage}" alt="已选择的参考图">`:icon(d.kind==='audio'?'audio-lines':'image-plus')}<div><strong>${d.reference?(d.kind==='audio'?'已选择合成录音示例':d.source?'来自 '+esc(d.source.id):'已选择商品参考图'):(d.kind==='audio'||d.kind==='vision'&&d.mode==='audio'?'输入录音':d.kind==='vision'&&d.mode==='video'?'视频素材':'参考图片')}</strong><small>${d.reference?'内置演示素材':'选择素材后继续'}</small></div>${plain(d.reference?'更换':'选择','reference')}</div>`+(d.kind==='image'&&d.mode==='inpaint'?check('重绘瓶身区域','mask',d.mask):'')+(d.kind==='audio'&&d.op==='vc'?check('用户声明：本次使用合成示例音色','consent',d.consent):'');}
function trialEditor(){const d=draft(),m=model(d.model),busy=!!d.running;return `<section class="nl-editor" aria-label="试用设置"><div><div class="nl-field-label"><small>模型</small>${m?.candidate?plain('来源实验','model-source',`data-id="${m.experiment}"`):''}</div><button class="nl-button nl-picker" data-action="pick-model" data-target="trial" ${busy?'disabled':''}><span>${esc(m?.name||'选择模型')}<small>${m?.ready?'已就绪 · 演示配置':'尚未下载'}${m?.candidate?' · 已登记候选':''}</small></span>${icon('chevron-down')}</button></div>${d.kind==='audio'?select('任务','op',d.op,Object.entries(audioOps),'trial',busy):d.kind==='image'?select('任务','mode',d.mode,[['t2i','文字生成图片'],['i2i','参考图生成图片'],['inpaint','局部重绘']],'trial',busy):d.kind==='video'?select('任务','mode',d.mode,[['i2v','图片生成视频'],['t2v','文字生成视频']],'trial',busy):d.kind==='vision'?select('任务','mode',d.mode,[['vqa','看图问答'],['json','结构化提取'],['video','视频理解'],...(model(d.model)?.base==='qwen-omni'?[['audio','音频理解']]:[])],'trial',busy):''}${referenceInput(d)}<div class="nl-field"><div class="nl-field-label"><label for="nl-prompt">${d.kind==='audio'&&d.op==='tts'?'配音文本':d.kind==='text'?'输入消息':d.kind==='vision'?'问题':'提示词'}</label>${plain(icon('sparkles')+'润色','polish',busy?'disabled':'')}</div><textarea id="nl-prompt" data-trial-field="prompt" ${busy?'disabled':''}>${esc(d.prompt)}</textarea></div>${d.aiUndo?`<small>已应用示例建议 ${plain('撤销','undo-polish')}</small>`:''}${d.kind==='audio'&&['tts','vc'].includes(d.op)?select('音色','voice',d.voice,['柔和女声 · 合成示例','自然男声 · 合成示例'],'trial',busy):''}${['image','video'].includes(d.kind)?`<div class="nl-field-row">${select('画面比例','size',d.size,['1:1','16:9','9:16'],'trial',busy)}${d.kind==='video'?select('时长','seconds',d.seconds,['3','5','8'],'trial',busy):field('随机种子','seed',d.seed,'trial','number',busy)}</div>`:''}${d.kind!=='image'?field('随机种子','seed',d.seed,'trial','number',busy):''}${runtimeEntry(d)}${d.error?`<div class="nl-error" role="alert">${esc(d.error)}</div>`:''}<div><button class="nl-button primary wide" data-action="generate" ${busy?'disabled':''}>${busy?icon('loader-circle')+'正在生成':icon('play')+(d.kind==='audio'&&d.op==='asr'?'开始转写':d.kind==='text'||d.kind==='vision'?'发送':'生成'+(d.kind==='audio'?audioOps[d.op]:kinds[d.kind]))}</button><small class="nl-example-note">${esc(store.settings.devices[store.settings.device].name)} · 演示执行</small></div></section>`;}
function resultContent(result,compact=false){if(!result)return `<div class="nl-empty">${icon(store.kind==='audio'?'audio-lines':store.kind==='text'?'messages-square':'image')}<strong>${store.kind==='audio'?'生成后在这里试听':'结果会出现在这里'}</strong><small>输入内容后直接生成，历史会留在当前页。</small></div>`;if(result.kind==='image')return art(result.sample?'示例效果':'生成演示 · 预置素材',Number(result.seed)%2!==0);if(result.kind==='video')return art('动态分镜演示 · 非模型视频',false,true);if(result.kind==='audio'&&result.op!=='asr')return `<div class="nl-audio-result">${waveform()}${audio(result.op==='music')}<small>${result.op==='music'?'程序生成的音乐示例':'系统合成语音示例'} · 非当前模型输出</small></div>`;if(result.kind==='audio')return `<div class="nl-answer"><small>转写示例 · 可编辑</small><label class="nl-field">字幕文本<textarea data-result-transcript="${result.id}">${esc(result.transcript||'00:00 欢迎来到声音工作台。\n00:02 这是一段试听示例。')}</textarea></label>${audio()}</div>`;return `<div class="nl-answer"><div class="nl-chat-user">${esc(result.prompt)}</div><strong>${esc(model(result.model)?.name||'模型')} · 预置回答</strong>${result.kind==='vision'?`<p>${result.recipe.mode==='audio'?'转写：欢迎来到声音工作台。<br>声音：合成语音示例':result.recipe.mode==='video'?'镜头：缓慢推近商品。<br>主体：浅色石台上的香水瓶。':result.recipe.mode==='json'?'&lbrace;主体: 香水瓶, 材质: 玻璃与金属, 颜色: 淡紫色与金色&rbrace;':'主体：香水瓶<br>材质：玻璃与金属<br>颜色：淡紫色与金色'}</p><small>这是所选演示素材的预置结果。</small>`:`<p>1. 选择适合任务的基座模型。<br>2. 准备有使用权限的数据，并保留独立验证集。<br>3. 先做小规模实验，比较效果后再扩大训练。</p><small>此回答用于展示对话布局。</small>`}</div>`;}
function resultCard(result,compact=false){const d=draft();return `<div class="nl-preview"><div class="nl-preview-top"><strong>${result?esc(result.id):'预览'}</strong><small>${result?esc(model(result.model)?.name||result.model):'等待输入'}</small></div>${resultContent(result,compact)}${result?.kind==='video'?`<div class="nl-video-controls">${plain(icon(media.playing?'pause':'play'), 'video-play',`aria-label="${media.playing?'暂停':'播放'}动态分镜演示"`)}<input type="range" min="0" max="100" value="${media.frame}" data-video-position aria-label="视频预览进度"><small class="nl-video-time">${(media.frame/20).toFixed(1)} / 5.0 秒</small></div>`:''}${result?`<div class="nl-preview-actions"><div class="nl-actions">${plain(icon(result.favorite?'bookmark-check':'bookmark')+(result.favorite?'已保存':'保存作品'),'favorite',`data-id="${result.id}" ${result.favorite?'aria-pressed="true"':'aria-pressed="false"'}`)}${!compact&&result.kind==='image'?plain('用于视频 '+icon('arrow-up-right'),'to-video',`data-id="${result.id}"`):''}</div>${plain('配方','recipe',`data-id="${result.id}"`)}</div>`:''}</div>`;}
function previewArea(){const d=draft(),result=trialResult(),job=store.jobs.find(x=>x.id===d.running),items=trialHistory();let out='';if(job&&['running','paused'].includes(job.status)){out=`<div class="nl-preview"><div class="nl-empty">${icon('loader-circle')}<strong>${job.status==='paused'?'任务已暂停':'正在生成'+(d.kind==='audio'?audioOps[d.op]:kinds[d.kind])}</strong><div class="nl-progress"><span style="width:${job.progress}%"></span></div><small>${job.progress}% · 演示进度</small>${btn('查看任务队列','queue')}</div></div>`;}else if(store.compare&&items.length>1){let other=items.find(x=>x.id===d.compareId&&x.id!==result.id)||items.find(x=>x.id!==result.id);out=`<div class="nl-comparison"><div><small>当前选择</small>${resultCard(result,true)}</div><div><select aria-label="选择对照结果" data-compare-id>${items.filter(x=>x.id!==result.id).map(x=>`<option value="${x.id}" ${x.id===other.id?'selected':''}>${x.id} · 种子 ${x.seed}</option>`).join('')}</select>${resultCard(other,true)}</div></div>`;}else out=resultCard(result);return `<section class="nl-result-area" aria-label="结果与历史">${out}<p class="nl-example-note">${store.kind==='image'||store.kind==='video'?'效果使用同一张摄影素材演示；提示词和种子只记录到配方。':'输入、执行与结果均为原型演示。'}</p>${result&&!d.running?`<div class="nl-actions" style="margin-top:8px">${btn('载入此配方继续修改','reuse',false,`data-id="${result.id}"`)}</div>`:''}<div class="nl-history"><div class="nl-history-head"><div class="nl-tabs"><button data-history-tab="history" aria-selected="${store.trialTab==='history'}">历史 ${items.length}</button><button data-history-tab="saved" aria-selected="${store.trialTab==='saved'}">已保存 ${items.filter(x=>x.favorite).length}</button></div>${plain(icon('columns-2')+(store.compare?'退出比较':'比较'),'compare',items.length<2?'disabled':'')}</div><div class="nl-history-list">${items.filter(x=>store.trialTab!=='saved'||x.favorite).slice(0,9).map(x=>`<button class="nl-history-item" data-result="${x.id}" aria-pressed="${result?.id===x.id}">${['image','video','vision'].includes(x.kind)?`<img src="${demoImage}" alt="${x.id} 的示意缩略图">`:`<div class="nl-thumb-icon">${icon(x.kind==='audio'?'audio-lines':'messages-square')}</div>`}<span>${esc(x.id)} · ${esc(x.seed)}</span></button>`).join('')}</div>${!items.length||store.trialTab==='saved'&&!items.some(x=>x.favorite)?'<small>还没有记录。</small>':''}</div></section>`;}
function trialScreen(){return trialHeader()+`<section id="nl-trial-panel" role="tabpanel" aria-labelledby="nl-kind-${store.kind}" class="nl-trial-layout">${trialEditor()}${previewArea()}</section>`;}
function moduleHeading(){return `<div class="nu-breadcrumb">${plain(icon('arrow-left')+'工作台','home')}<span>/</span><span>${modules[store.module].name}</span></div>`+heading(modules[store.module].name+(store.mode==='train'?'训练 / 微调':store.mode==='trial'?'运行 / 试用':'任务与结果'),'模型、数据、运行与结果保留在当前流程。',btn('新建训练任务','new-training'))+`<div class="nl-tabs nu-module-tabs" role="tablist" aria-label="当前类别功能">${[['train','训练 / 微调'],['trial','运行 / 试用'],['history','任务与结果']].map(([k,n])=>`<button role="tab" aria-selected="${store.mode===k}" data-module-mode="${k}">${n}</button>`).join('')}</div>`;}
function homeScreen(){const recent=store.experiments.filter(x=>x.project===store.project).slice(0,4);return heading('工作台','选择要训练或微调的模型类别。')+`<div class="nu-home-grid">${Object.entries(modules).map(([key,m])=>`<section class="nu-home-entry"><div class="nu-entry-icon">${icon(m.icon)}</div><h2>${m.name}</h2><p>${m.description}</p><small>${m.methods}</small><button class="nl-button primary" data-enter-module="${key}">开始训练 / 微调 ${icon('arrow-right')}</button></section>`).join('')}</div><div class="nl-heading nu-section-heading"><h2>继续最近任务</h2>${plain('查看运行队列','queue')}</div><div class="nl-panel">${recent.map(d=>taskRow(d)).join('')||'<div class="nl-empty-list">创建训练任务后，在这里继续。</div>'}</div><div class="nu-home-links">${btn(icon('boxes')+'查找模型与工作流','models')}${btn(icon('database')+'浏览数据集市场','market')}${btn(icon('flask-conical')+'进入模型实验室','lab')}</div><p class="nl-example-note">所有训练、下载、AI 建议与评测均为交互演示。当前不调用真实模型或外部服务。</p>`;}
function taskRow(d){const name=d.status==='draft'?'继续配置':d.status==='complete'?d.candidates.length?'查看结果':'继续评测':d.status==='failed'?'查看失败原因':'查看运行';return `<div class="nl-resource-row"><div><strong>${esc(d.name)}</strong><small>${d.id} · ${d.type==='train'?modules[d.module].short+' · '+methodNames[d.method]:expTypes[d.type]}${d.source?' · 来自 '+d.source:''}</small></div><div class="nl-actions">${tag(d.status==='complete'?(d.candidates.length?'已登记':d.review?'待选择候选':'待评测'):statusName(d.status),d.status==='complete'?'good':d.status==='failed'?'warn':'')}${btn(name,'open-exp',false,`data-id="${d.id}"`)}</div></div>`;}
function taskHistory(){const list=store.experiments.filter(x=>x.project===store.project&&x.module===store.module);const jobs=store.jobs.filter(x=>x.project===store.project&&x.module===store.module&&x.type==='trial');return `<section class="nl-panel"><h2>训练与实验</h2>${list.map(taskRow).join('')||'<div class="nl-empty-list">本类别还没有训练记录。</div>'}</section><section class="nl-panel"><h2>运行与生成</h2>${jobs.map(j=>`<div class="nl-resource-row"><div><strong>${esc(j.name)}</strong><small>${j.id} · ${statusName(j.status)}</small></div>${btn('查看任务','open-job',false,`data-id="${j.id}"`)}</div>`).join('')||'<div class="nl-empty-list">运行模型后，结果自动保留在这里。</div>'}</section>`;}
function moduleScreen(){return moduleHeading()+(store.mode==='trial'?workflowBanner()+trialScreen():store.mode==='history'?taskHistory():experimentScreen());}
function experimentScreen(){const d=currentExp();if(!d)return '<div class="nl-empty-list">选择一项任务继续，或新建任务。</div>';const names=[['config','配置'],['run','运行'],['eval','评测与产物']];return `<div class="nu-task-heading"><div><strong>${esc(d.name)}</strong><small>${d.id} · ${esc(model(d.model)?.name)}${d.source?' · 源任务 '+d.source:''}</small></div>${tag(statusName(d.status),d.status==='failed'?'warn':d.status==='complete'?'good':'')}</div><div class="nl-tabs nu-detail-tabs" role="tablist" aria-label="任务流程">${names.map(([k,n])=>`<button role="tab" id="nu-exp-${k}" aria-controls="nu-exp-panel" aria-selected="${d.tab===k}" data-exp-tab="${k}">${n}</button>`).join('')}</div><section id="nu-exp-panel" role="tabpanel" aria-labelledby="nu-exp-${d.tab}">${d.tab==='config'?expConfig(d):d.tab==='run'?expRun(d):expEval(d)}</section>`;}
function expConfig(d){const locked=d.status!=='draft';if(locked)return `<div class="nl-note">本次配置已固定，可以查看原始输入或复制为新尝试。</div><div class="nl-panel">${kv('模型',esc(model(d.snapshot.model)?.name))}${kv('训练类型',d.type==='train'?methodNames[d.snapshot.method]:expTypes[d.type])}${kv('参数更新',adaptNames[d.snapshot.adapt])}${kv('数据版本',esc(dataFor(d)?.name)+' · '+esc(d.snapshot.dataVersion||dataFor(d)?.version))}${kv('步数 / 批量',d.snapshot.steps+' / '+d.snapshot.batch)}${kv('使用范围声明',esc(d.snapshot.sourceStatement||'用户未填写'))}${btn('复制配置，新建尝试','retry-exp')}</div>`;return `<nav class="nu-steps" aria-label="配置步骤">${['模型与方法','准备数据','参数与环境'].map((n,i)=>`<button data-config-step="${i}" aria-current="${d.step===i?'step':'false'}"><span>${i+1}</span>${n}</button>`).join('')}</nav>${d.error?`<div class="nl-error" role="alert">${esc(d.error)}</div>`:''}${d.step===0?trainingModelPanel(d):d.step===1?trainingDataPanel(d):trainingParameters(d)}<div class="nl-submitbar"><small>${d.step===0?'选择后展示适用的数据与参数。':d.step===1?'技术检查只检查数据能否被读取。':'确认本次输入后，由你启动执行。'}</small><div class="nl-actions">${d.step?btn('上一步','config-back'):''}${d.step<2?btn('继续：'+['准备数据','参数与环境'][d.step],'config-next',true):btn(icon('play')+'检查并启动','preflight',true)}</div></div>`;}
function trainingModelPanel(d){const m=model(d.model);let methodPart='';if(d.type==='train')methodPart=select('训练类型','method',d.method,optionsFor(d).map(k=>[k,methodNames[k]]),'exp')+select('参数更新方式','adapt',d.adapt,adaptFor(d).map(k=>[k,adaptNames[k]]),'exp')+`<div class="nl-note"><strong>${methodNames[d.method]} + ${adaptNames[d.adapt]}</strong><p>${methodDescription(d)}</p></div>`;else if(d.type==='armor')methodPart=select('研究方法','engine',d.engine,[['compare','Heretic + Abliterix 独立对照'],['heretic','Heretic 基线'],['abliterix','Abliterix 对照'],['research','自研方案 · 尚无执行流程']],'exp')+'<small>保留两个引擎的输入、预算与独立候选，统一评测。</small>';else if(d.type==='distill')methodPart=select('教师模型','teacher',d.teacher,['Qwen3-8B · 教师示例','同类教师模型 · 示例'],'exp')+'<small>准备教师回答，与学生原模型进行独立对比。</small>';else if(d.type==='merge')methodPart=`<div class="nl-field-row">${select('适配器 A','adapterA',d.adapterA,['客服适配器 A','写作适配器 B'],'exp')}${select('适配器 B','adapterB',d.adapterB,['客服适配器 A','写作适配器 B'],'exp')}</div><small>本例两个适配器关联相同基座；执行前检查结构与版本。</small>`;else methodPart=select(d.type==='convert'?'导出格式':'量化格式','format',d.format,d.type==='convert'?['Core ML FP16','ONNX FP32','TorchScript']:['GGUF Q4','GGUF Q8','MLX 4-bit'],'exp')+'<small>转换后的运行模型保留源权重关系，不能直接当作训练基座。</small>';return `<section class="nl-panel"><div class="nu-panel-heading"><h2>模型与方法</h2>${tag('适配配置演示')}</div><div class="nl-fields">${field('任务名称','name',d.name,'exp')}<div class="nl-field">基座模型<button class="nl-button nl-picker" data-action="pick-model" data-target="experiment"><span>${esc(m.name)}<small>${m.ready?'组件已准备 · 演示':'需要下载组件'} · ${m.inputs}</small></span>${icon('chevron-down')}</button></div>${methodPart}${d.type==='train'&&(d.kind==='vision'||d.adapt==='partial')?select('训练范围','target',d.target,d.kind==='vision'?['语言部分 + 连接层','仅连接层','语言与视觉部分']:['默认推荐模块','仅输出层','指定特征层'],'exp'):''}<div class="nu-kv-summary">${kv('需要的数据',schemaInfo[schemaFor(d)].name)}${kv('输出产物',outputType(d))}</div></div></section>`;}
function methodDescription(d){return ({sft:'用指令、对话或多模态配对样例学习目标回答。',cpt:'用连续领域文本继续训练，保留独立验证语料。',dpo:'使用同一问题下的优选与非优选回答对。',grpo:'使用问题、可验证答案与奖励规则，比较多次生成。',ppo:'使用提示词和奖励模型，记录奖励与能力回归。',diffusion:'用图片和描述适配画面风格与领域内容。',dreambooth:'围绕特定主体训练，配置触发词和主体样例。',paired:'使用源图、参考图、目标图进行监督训练。',video:'用镜头片段与描述学习目标动作和画面风格。',tts:'使用录音、转写和说话人标识适配语音合成。',asr:'使用录音与准确转写适配识别任务。',vc:'使用目标音色录音，提取音高和声音特征。',music:'使用音乐片段与描述适配风格和声音内容。'})[d.method];}
function trainingMediaPreview(d){if(['image','video','vision'].includes(d.kind))return `<details class="nl-advanced"><summary>${d.kind==='video'?'查看关键帧与镜头描述':'查看图片与标注'}</summary><div class="nu-training-preview">${art(d.kind==='video'?'关键帧示例':'训练样例预览')}<label class="nl-field">本次样例标注<textarea data-exp-field="annotation" placeholder="可在任务副本中补充标注，保留原始数据。">${esc(d.annotation)}</textarea></label></div></details>`;if(d.kind==='audio')return `<details class="nl-advanced"><summary>试听录音与切片设置</summary><div class="nl-fields" style="margin-top:12px">${audio(d.method==='music')}<div class="nl-field-row">${field('片段开始（秒）','trimStart',d.trimStart,'exp','number')}${field('片段结束（秒）','trimEnd',d.trimEnd,'exp','number')}</div><label class="nl-field">转写 / 描述<textarea data-exp-field="annotation" placeholder="补充当前样例的文字内容。">${esc(d.annotation)}</textarea></label><small>切片参数保留在本次配方中。试听使用内置音频。</small></div></details>`;return '';}
function trainingDataPanel(d){const data=dataFor(d),schema=schemaInfo[schemaFor(d)];return `<section class="nl-panel"><div class="nu-panel-heading"><h2>准备训练数据</h2>${plain('浏览数据集市场','browse-market')}</div><div class="nl-note"><strong>${schema.name}</strong><p>必需字段：${schema.fields}</p></div><div class="nl-fields"><button class="nl-button nl-picker" data-action="pick-data"><span>${data?esc(data.name):'选择数据集'}<small>${data?data.count+' 条 · '+data.version:'从我的数据或数据集市场选择'}</small></span>${icon('chevron-down')}</button>${data?`${trainingMediaPreview(d)}<div class="nu-data-preview"><div class="nu-panel-heading"><strong>样例预览</strong>${plain('查看完整信息','data-detail',`data-id="${data.id}"`)}</div><pre>${esc(data.rows?JSON.stringify(data.rows[0],null,2):schema.sample)}</pre></div><details class="nl-advanced"><summary>来源与使用范围 · 用户声明</summary><div class="nl-fields" style="margin-top:12px"><small>来源：${esc(data.source)}</small><small>提供方原文：${esc(data.terms)}</small><label class="nl-field">本次使用范围声明<textarea data-exp-field="sourceStatement" placeholder="由你填写；系统和 AI 不作授权或合法性判定。">${esc(d.sourceStatement)}</textarea></label></div></details><div class="nl-field-row">${select('技术检查样例','fixture',d.fixture,[['clean','字段完整'],['missing','包含缺失字段'],['duplicate','包含重复样本']],'exp')}${field('验证集比例（%）','split',d.split,'exp','number')}</div><div class="nl-actions">${btn(icon('scan-line')+'运行技术检查','check-data',true)}${d.fixture==='missing'?btn('排除缺失记录','exclude-missing',false,d.excluded?'disabled':''):''}${d.fixture==='duplicate'?btn('去除重复记录','dedup-data',false,d.deduped?'disabled':''):''}</div>${d.dataIssues?`<div class="nu-check-report"><strong>技术检查结果</strong>${kv('必需字段',d.dataIssues.missing?d.dataIssues.missing+' 条缺失':'完整')}${kv('重复记录',d.dataIssues.duplicates?d.dataIssues.duplicates+' 条，建议处理':'未发现')}${kv('数据划分','训练 '+(100-Number(d.split))+'% / 验证 '+d.split+'%')}${kv('本次处理',d.excluded?'在任务副本中排除缺失记录':d.deduped?'在任务副本中去重':'未修改原始数据')}<small>不评判来源或授权，不自动清洗数据。</small></div>`:''}`:`<div class="nl-empty-list">先选择与 ${methodNames[d.method]||expTypes[d.type]} 格式匹配的数据。</div>`}</div></section>`;}
function trainingParameters(d){const train=d.type==='train',lowRank=['lora','qlora'].includes(d.adapt);let special='';if(train&&d.kind==='text'||train&&d.kind==='vision')special=field('最大序列长度','length',d.length,'exp','number');if(train&&['image','video'].includes(d.kind))special=select('训练分辨率','resolution',d.resolution,['256','512','768','1024'],'exp');if(train&&d.method==='dreambooth')special+=field('主体触发词','trigger',d.trigger,'exp');if(train&&d.kind==='video')special+=`<div class="nl-field-row">${select('每段帧数','frames',d.frames,['17','33','49'],'exp')}${select('帧率','fps',d.fps,['8','16','24'],'exp')}</div>`;if(train&&d.kind==='audio')special+=select('音频采样率','sampleRate',d.sampleRate,['16000','24000','44100'],'exp')+'<small>预处理按任务完成切片、转写或音高特征准备。</small>';if(d.method==='grpo')special+=select('奖励规则','reward',d.reward,[['exact','答案精确匹配'],['format','结构化输出检查']],'exp');if(d.method==='ppo')special+=select('奖励模型','rewardModel',d.rewardModel,['奖励模型 · 示例','自定义奖励模型 · 待准备'],'exp');if(d.type==='armor')special=`<div class="nl-field-row">${field('候选预算','budget',d.budget,'exp','number')}${field('能力下降容许值（百分点）','quality',d.quality,'exp','number')}</div>`;if(d.type==='merge')special=field('适配器 A 权重（B = 1 − A）','weight',d.weight,'exp','number');return `<section class="nl-panel"><div class="nu-panel-heading"><h2>参数与执行环境</h2>${plain(icon('sparkles')+'让 AI 给建议','suggest-parameters')}</div><div class="nl-fields">${!['quantize','convert','merge'].includes(d.type)?`<div class="nl-field-row">${field('训练步数','steps',d.steps,'exp','number')}${field('学习率','rate',d.rate,'exp','number')}</div><div class="nl-field-row">${field('每设备批量','batch',d.batch,'exp','number')}${select('梯度累积步数','accum',d.accum,['1','2','4','8'],'exp')}</div>${train&&lowRank?select('LoRA 秩','rank',d.rank,['8','16','32','64'],'exp'):''}`:''}${special}${select('执行设备','device',d.device,Object.entries(store.settings.devices).map(([k,v])=>[k,v.name]),'exp')}<div class="nu-device-strip"><span>${store.settings.devices[d.device].ready?'演示连接可用':'尚未连接'} · ${store.settings.devices[d.device].engine}</span>${plain('配置设备','settings')}</div><details class="nl-advanced"><summary>高级参数</summary><div class="nl-fields" style="margin-top:12px">${field('随机种子','seed',d.seed,'exp','number')}<small>检查点、优化器与精度设置按适配模板记录。本原型不估算真实训练耗时或费用。</small></div></details><div class="nu-kv-summary">${kv('更新方式',adaptNames[d.adapt])}${kv('产物',outputType(d))}${kv('数据',esc(dataFor(d)?.name||'未选择'))}</div></div></section>`;}
function expRun(d){const loss=d.progress?Math.max(.38,1.9-d.progress*.014).toFixed(2):'—';return `<div class="nl-run-grid"><section class="nl-panel"><div class="nl-run-status"><h2>${statusName(d.status)}</h2><strong>${d.progress}%</strong></div><div class="nl-progress" role="progressbar" aria-label="任务演示进度" aria-valuenow="${d.progress}" aria-valuemin="0" aria-valuemax="100"><span style="width:${d.progress}%"></span></div><div class="nu-run-metrics">${kv('训练步数',Math.round(Number(d.steps)*d.progress/100)+' / '+d.steps)}${kv('损失 · 模拟',loss)}</div><div class="nl-logs" aria-label="运行日志">${d.logs.map((l,i)=>`<div>${String(i+1).padStart(2,'0')}　${esc(l)}</div>`).join('')||'由你启动后显示运行记录。'}</div><div class="nl-actions" style="margin-top:18px">${d.status==='running'?btn('暂停','pause-job',false,`data-id="${d.id}"`):d.status==='paused'?btn('继续执行','resume-job',true,`data-id="${d.id}"`):''}${['running','paused'].includes(d.status)?plain('取消任务','cancel-job',`data-id="${d.id}"`):''}${d.status==='complete'?btn('进入评测与产物','tab-eval',true):['failed','cancelled'].includes(d.status)?btn('复制配置并重试','retry-exp',true):''}</div></section><section class="nl-panel"><h2>本次执行</h2>${kv('任务',d.id)}${kv('设备',store.settings.devices[d.device].name)}${kv('模型',esc(model(d.model)?.name))}${kv('方法',d.type==='train'?methodNames[d.method]+' / '+adaptNames[d.adapt]:expTypes[d.type])}${kv('数据声明',d.sourceStatement?'用户已填写':'用户未填写')}<details class="nl-advanced"><summary>演示失败分支</summary>${btn('模拟显存不足','fail-exp',false,!['running','paused'].includes(d.status)?'disabled':'')}</details></section></div><p class="nl-example-note">进度、损失与日志为模拟值。任务可以在后台继续；AI 不会暂停或重启任务。</p>`;}
function expEval(d){if(d.status!=='complete')return `<div class="nl-panel"><div class="nl-empty">${icon('clipboard-check')}<strong>执行完成后开始评测</strong><small>评测由你触发，候选登记也由你决定。</small>${btn('查看运行记录','tab-run')}</div></div>`;const names=d.kind==='image'?['画面与主体','结构完整','样例对照']:d.kind==='video'?['镜头连贯','主体稳定','样例对照']:d.kind==='audio'?['音频质量','文本一致','样例对照']:['任务能力','输出格式','行为回归'];return `<div class="nl-heading"><div><h2>比较并选择候选</h2><small>预置评测场景 · 不代表真实模型效果</small></div><div class="nl-actions">${btn(d.review?'重新评测':'开始评测','evaluate',true,d.candidates.length?'disabled':'')}${plain('查看失败场景','eval-fail',d.candidates.length?'disabled':'')}</div></div>${d.review?`<div class="nl-table-wrap"><table class="nl-table nl-eval-table"><thead><tr><th>候选</th><th>${names[0]}</th><th class="nl-mobile-hide">${names[1]}</th><th>${names[2]}</th><th></th></tr></thead><tbody>${d.review.map((r,i)=>`<tr><td><strong>${r.name}</strong><small>${i===0?'对照基线':outputType(d)}</small></td><td class="${r.quality==='通过'?'good':'warn'}">${r.quality}</td><td class="nl-mobile-hide">${r.format}</td><td class="${r.behavior==='通过'?'good':'warn'}">${r.behavior}</td><td>${!i?'':r.registered?btn('运行 / 试用','try-candidate',false,`data-id="${d.id+'-candidate-'+i}"`):btn('登记候选','register',false,`data-index="${i}" ${r.quality!=='通过'||r.behavior!=='通过'?'disabled':''}`)}</td></tr>`).join('')}</tbody></table></div><section class="nl-panel" style="margin-top:16px"><h2>样例对照</h2>${['image','video'].includes(d.kind)?`<div class="nl-comparison">${art('原模型 · 预置素材')}${art('候选 · 同一预置素材')}</div>`:d.kind==='audio'?audio():'<div class="nu-answer-pair"><p><strong>原模型样例</strong><br>建议联系商家了解详情。</p><p><strong>候选样例</strong><br>先核对订单、渠道和适用条款；信息不足时先询问。</p></div>'}<small>评测样例为预置内容，不能用于判断真实改进。</small></section>`:'<div class="nl-empty-list">产物已准备。点击“开始评测”查看对比与样例。</div>'}<div class="nl-submitbar"><small>候选保留源模型、数据版本和本次配置。</small><div class="nl-actions">${btn('查看模型库','models')}${plain('复制配置再试一次','retry-exp')}</div></div>`;}
function labScreen(){const d=currentExp();return heading('模型实验室','开展模型处理和研究，保留独立输入、运行与候选。',d?btn('返回实验列表','lab-list'):btn('新建专项实验','create',true))+(d?experimentScreen():`<div class="nu-lab-grid">${Object.entries(expTypes).filter(([k])=>k!=='train').map(([k,n])=>`<button class="nu-lab-entry" data-create-type="${k}"><strong>${n}</strong><small>${({armor:'Heretic / Abliterix · 双引擎对照',distill:'教师回答 → 学生训练 → 对比',merge:'检查兼容性 → 配比 → 合并',quantize:'运行格式 → 质量对比 → 候选',convert:'Core ML / ONNX / TorchScript'})[k]}</small>${icon('arrow-right')}</button>`).join('')}</div><section class="nl-panel"><h2>近期实验</h2>${store.experiments.filter(x=>x.project===store.project&&x.type!=='train').map(taskRow).join('')||'<div class="nl-empty-list">选择上方方法开始。</div>'}</section>`);}
function originBar(){return store.origin?`<div class="nu-origin"><div><strong>来自 ${esc(store.origin.name)}</strong><small>选择资源后继续原来的配置。</small></div>${btn('返回原任务','return-origin')}</div>`:'';}
function modelsScreen(){const list=store.models.filter(m=>(!m.project||m.project===store.project)&&(store.modelFilter==='all'||m.module===store.modelFilter));return heading('模型库','下载模型、准备运行环境，运行模型或工作流。',btn(icon('download')+'导入模型','import-model'))+originBar()+`<div class="nl-tabs"><button data-model-tab="models" aria-selected="${store.modelTab==='models'}">模型</button><button data-model-tab="workflows" aria-selected="${store.modelTab==='workflows'}">工作流</button></div>`+(store.modelTab==='workflows'?`<div class="nu-workflow-grid">${store.workflows.map(w=>`<section class="nl-panel"><h2>${w.name}</h2><p>${w.description}</p><div class="nu-node-flow">${w.nodes.map((x,i)=>`<span>${i+1}. ${x}</span>`).join('')}</div><div class="nl-actions">${btn('查看并运行','workflow-detail',true,`data-id="${w.id}"`)}</div></section>`).join('')}</div>`:`<div class="nu-filter">${select('模型类别','modelFilter',store.modelFilter,[['all','全部类别'],...Object.entries(modules).map(([k,m])=>[k,m.short])],'view')}</div><section class="nl-panel"><div class="nl-resource-list">${list.map(m=>{const j=downloadJob(m.id);return `<div class="nl-resource-row"><div><strong>${esc(m.name)}</strong><small>${modules[m.module].short} · ${esc(m.format)}</small>${tag(m.ready?'演示组件已准备':j?statusName(j.status)+' '+j.progress+'%':'尚未下载',m.ready?'good':'')}${m.candidate?`<small>来源 ${m.experiment}</small>`:''}</div><div class="nl-actions">${btn('详情','model-detail',false,`data-id="${m.id}"`)}${m.ready?btn('运行','try-model',true,`data-id="${m.id}"`):btn(j&&['running','paused'].includes(j.status)?'查看下载':'下载','download-model',true,`data-id="${m.id}"`)}${m.ready&&!m.runtimeOnly?plain('训练 / 微调','train-model',`data-id="${m.id}"`):''}</div></div>`;}).join('')}</div></section>`)+`<p class="nl-example-note">清单与支持组合用于演示界面。真实适配、模型版本与运行环境尚未接入。</p>`;}
function downloadJob(id,type='download'){return store.jobs.find(j=>j.type===type&&(type==='download'?j.model===id:j.dataset===id)&&['running','paused'].includes(j.status));}
function dataScreen(){const list=store.datasets.filter(d=>(store.marketTab==='discover'||d.ready)&&(store.marketFilter==='all'||d.kind===store.marketFilter));return heading('数据集市场','发现、下载和整理数据，在训练中复用。',btn(icon('plus')+'导入数据','import-data',true))+originBar()+`<div class="nl-tabs"><button data-market-tab="discover" aria-selected="${store.marketTab==='discover'}">发现数据</button><button data-market-tab="mine" aria-selected="${store.marketTab==='mine'}">我的数据</button></div><div class="nu-filter">${select('数据类别','marketFilter',store.marketFilter,[['all','全部类别'],...Object.entries(kinds)],'view')}</div><div class="nu-data-grid">${list.map(d=>`<section class="nl-panel"><div class="nu-panel-heading">${tag(schemaInfo[d.schema].name)}${tag(d.ready?'已下载':d.access==='request'&&d.accessStatus!=='granted'?'需申请访问':'在线样例',d.ready?'good':'')}</div><h2>${esc(d.name)}</h2><p>${d.count} 条 · ${d.version}</p><small>来源：${esc(d.provider)}<br>使用范围：${esc(d.statement==='未填写'?'用户未填写':d.statement)}</small><div class="nl-actions" style="margin-top:16px">${btn('预览与详情','data-detail',false,`data-id="${d.id}"`)}${d.ready?btn(store.origin&&chosenExp(store.origin.exp)&&d.schema!==schemaFor(chosenExp(store.origin.exp))?'格式不匹配':store.origin?'用于原任务':'用于训练','train-data',true,`data-id="${d.id}" ${store.origin&&chosenExp(store.origin.exp)&&d.schema!==schemaFor(chosenExp(store.origin.exp))?'disabled':''}`):btn(downloadJob(d.id,'dataset')?'查看进度':d.access==='request'&&d.accessStatus!=='granted'?'申请访问':'下载','download-data',true,`data-id="${d.id}"`)}</div></section>`).join('')}</div><p class="nl-example-note">来源与使用范围由提供方或用户填写。平台和 AI 不作合法性、授权判定。</p>`;}
function assetsScreen(){const results=Object.entries(store.histories).filter(([key])=>key.startsWith(store.project+'|')).flatMap(([,items])=>items).filter(r=>r.favorite);return heading('作品与素材','保留生成结果、配方和输入素材，继续用于其他流程。')+`<div class="nl-tabs"><button data-asset-tab="works" aria-selected="${store.assetTab==='works'}">已保存作品</button><button data-asset-tab="materials" aria-selected="${store.assetTab==='materials'}">输入素材</button></div>`+(store.assetTab==='materials'?`<div class="nu-data-grid"><section class="nl-panel">${art('商品参考图 · 预置素材')}<h2>商品参考图</h2>${btn('用于图片运行','use-asset',true,'data-kind="image"')}${btn('用于视频运行','use-asset',false,'data-kind="video"')}</section><section class="nl-panel"><h2>合成声音样例</h2>${audio()}${btn('用于转写','use-asset',true,'data-kind="audio"')}</section></div>`:`<div class="nu-data-grid">${results.map(r=>`<section class="nl-panel">${['image','video','vision'].includes(r.kind)?art('作品示意'):r.kind==='audio'?audio(r.op==='music'):'<p>对话结果与配方</p>'}<h2>${esc(r.id)}</h2><small>${esc(model(r.model)?.name)}</small><div class="nl-actions">${btn('打开结果','open-asset',true,`data-id="${r.id}" data-kind="${r.kind}"`)}${btn('查看配方','asset-recipe',false,`data-id="${r.id}" data-kind="${r.kind}"`)}</div></section>`).join('')||'<div class="nl-empty-list">在运行结果里点击“保存作品”，即可在此处复用。</div>'}</div>`);}
function resultById(id){return Object.entries(store.histories).filter(([key])=>key.startsWith(store.project+'|')).flatMap(([,items])=>items).find(x=>x.id===id);}
function modal(title,body,footer=''){return `<div class="nl-backdrop"><section class="nl-dialog" role="dialog" aria-modal="true" aria-label="${title}"><div class="nl-dialog-head"><h2>${title}</h2>${plain(icon('x'),'close-overlay','aria-label="关闭"')}</div>${body}${footer?`<div class="nl-dialog-foot">${footer}</div>`:''}</section></div>`;}
function modelPicker(o){const e=currentExp(),list=o.target==='experiment'?store.models.filter(m=>m.module===e.module&&!m.runtimeOnly&&(!m.project||m.project===store.project)):compatibleModels();return modal('选择模型',`<div class="nl-resource-list">${list.map(m=>`<div class="nl-resource-row"><div><strong>${esc(m.name)}</strong><small>${m.inputs} · ${m.format}</small>${tag(m.ready?'组件已准备':'尚未下载')}</div><div class="nl-actions">${m.ready?btn('选择','choose-model',true,`data-id="${m.id}"`):btn(downloadJob(m.id)?'下载中':'下载组件','download-model',false,`data-id="${m.id}" ${downloadJob(m.id)?'disabled':''}`)}</div></div>`).join('')}</div><small>这里显示演示适配组合；选择后回到原来的配置位置。</small>`);}
function dataDetail(o){const d=store.datasets.find(x=>x.id===o.id);return modal('数据详情 · '+esc(d.name),`<div class="nu-panel-heading">${tag(d.ready?'已下载':'在线样例')}${tag(schemaInfo[d.schema].name)}</div>${kv('数量 / 版本',d.count+' 条 / '+d.version)}<div class="nu-data-preview"><strong>样例内容</strong><pre>${esc(d.rows?JSON.stringify(d.rows.slice(0,2),null,2):schemaInfo[d.schema].sample)}</pre></div><div class="nl-fields">${field('来源记录','source',o.source??d.source,'dataMeta')}<label class="nl-field">提供方原始说明<textarea readonly>${esc(d.terms)}</textarea></label><label class="nl-field">使用范围 · 用户声明<textarea data-data-meta="statement" placeholder="由你填写，不由 AI 认定。">${esc(o.statement??(d.statement==='未填写'?'':d.statement))}</textarea></label><small>只记录原文与用户声明，不生成“已合法”或“已获授权”的结论。</small></div>`,btn('保存声明','save-statement')+(d.ready?btn(store.origin&&chosenExp(store.origin.exp)&&d.schema!==schemaFor(chosenExp(store.origin.exp))?'格式不匹配':store.origin?'用于原任务':'用于训练','train-data',true,`data-id="${d.id}" ${store.origin&&chosenExp(store.origin.exp)&&d.schema!==schemaFor(chosenExp(store.origin.exp))?'disabled':''}`):btn(downloadJob(d.id,'dataset')?'下载中':d.access==='request'&&d.accessStatus!=='granted'?'申请访问':'下载演示','download-data',true,`data-id="${d.id}" ${downloadJob(d.id,'dataset')?'disabled':''}`)));}
function settingsModal(o){const tab=o.tab||'devices';let body='';if(tab==='devices')body=hardwareSettings();else if(tab==='runtime')body=runtimeLibraries();else body=`<div class="nl-fields">${select('服务来源','ai',store.settings.ai,[['local','本地模型服务'],['remote','远程模型服务']],'settings')}${field('API 地址','aiEndpoint',store.settings.aiEndpoint,'settings')}${field('模型名称','aiModel',store.settings.aiModel,'settings')}<label class="nl-field">凭证<input type="password" placeholder="演示中不需要填写真实密钥" autocomplete="off"></label>${btn(store.settings.aiReady?'重新测试连接':'测试连接','connect-ai')}${tag(store.settings.aiReady?'演示连接可用':'尚未检查')}<small>本例的建议全部预置，不发送输入到任何服务。AI 无权自动修改配置、启动任务或判定数据授权。</small></div>`;return modal('设备、运行库与 AI',`<div class="nl-tabs">${[['devices','设备'],['runtime','运行库'],['ai','AI 连接']].map(([k,n])=>`<button data-settings-tab="${k}" aria-selected="${tab===k}">${n}</button>`).join('')}</div>${body}`,btn('完成','close-overlay',true));}
function queueModal(){return modal('任务队列',store.jobs.length?`<div class="nl-resource-list">${store.jobs.slice().reverse().map(j=>`<div class="nl-resource-row"><div><strong>${esc(j.name)}</strong><small>${j.id} · ${esc(j.project)} · ${statusName(j.status)} ${['running','paused'].includes(j.status)?j.progress+'%':''}</small>${['running','paused'].includes(j.status)?`<div class="nl-progress"><span style="width:${j.progress}%"></span></div>`:''}</div><div class="nl-actions">${j.status==='running'?plain('暂停','pause-job',`data-id="${j.id}"`):j.status==='paused'?plain('继续','resume-job',`data-id="${j.id}"`):''}${['running','paused'].includes(j.status)?plain('取消','cancel-job',`data-id="${j.id}"`):''}${!['download','dataset'].includes(j.type)?btn('打开任务','open-job',false,`data-id="${j.id}"`):''}</div></div>`).join('')}</div>`:'<div class="nl-empty-list">下载、训练和生成任务会显示在这里。</div>');}
function workflowDetail(w){return modal('工作流 · '+w.name,`<p>${w.description}</p><div class="nu-node-flow">${w.nodes.map((n,i)=>`<span>${i+1}. ${n}</span>`).join('')}</div><h2>依赖准备</h2><div class="nl-resource-list">${w.models.map(id=>{const m=model(id);return `<div class="nl-resource-row"><div><strong>${m.name}</strong>${tag(m.ready?'演示组件已准备':'缺少模型')}</div>${!m.ready?btn(downloadJob(id)?'下载中':'下载组件','download-model',false,`data-id="${id}" ${downloadJob(id)?'disabled':''}`):''}</div>`;}).join('')}</div><small>每一步由你确认后执行，结果保留在对应运行页。</small>`,btn('载入工作流','start-workflow',true,`data-id="${w.id}" ${w.models.some(id=>!model(id).ready)?'disabled':''}`));}
function overlay(){const o=store.overlay;if(!o)return '';const e=currentExp();if(o.type==='runtime')return runtimeModal(o);if(o.type==='access'){const data=store.datasets.find(x=>x.id===o.id);return modal('向提供方申请访问',kv('数据集',esc(data.name))+kv('状态',({none:'尚未申请',pending:'等待提供方处理',granted:'提供方开放下载 · 演示',rejected:'提供方未开放下载 · 演示'})[data.accessStatus])+`<label class="nl-field">申请用途<textarea data-access-purpose>${esc(o.purpose)}</textarea></label><small>申请由提供方处理。开放下载不代表平台或 AI 对来源、许可作出认定。本页不会发送真实申请。</small>${o.error?`<div class="nl-error" role="alert">${o.error}</div>`:''}${data.accessStatus==='pending'?`<details class="nl-advanced"><summary>演示提供方处理结果</summary>${btn('演示提供方通过','access-grant')}${btn('演示提供方拒绝','access-reject')}</details>`:''}`,data.accessStatus==='granted'?btn('下载数据','download-data',true,`data-id="${data.id}"`):data.accessStatus==='pending'?btn('返回继续工作','close-overlay'):btn('提交访问申请演示','send-access',true));}if(o.type==='models')return modelPicker(o);if(o.type==='queue')return queueModal();if(o.type==='settings')return settingsModal(o);if(o.type==='data-detail')return dataDetail(o);if(o.type==='workflow')return workflowDetail(store.workflows.find(w=>w.id===o.id));if(o.type==='device'){const d=store.settings.devices[o.id];return modal('设备配置 · '+d.name,`<div class="nl-fields">${field('地址 / 实例标识','host',d.host,'device')}${field('用户','user',d.user||'research','device')}${select('运行环境','engine',d.engine,o.id==='local'?['MLX / PyTorch','Core ML']:o.id==='amd'?['ROCm / PyTorch','HIP / llama.cpp','Vulkan / llama.cpp']:o.id==='intel'?['oneAPI / SYCL','OpenVINO']:o.id==='cpu'?['CPU']:['CUDA / PyTorch','ComfyUI / CUDA'],'device')}${select('连接方式','auth',d.auth||'ssh',['ssh','token'],'device')}<small>仅记录演示配置，不读取 SSH 密钥，不申请云资源。</small>${tag(d.ready?'演示连接可用':'未连接')}</div>`,btn('保存配置','save-device')+btn('模拟连接检查','connect',true,`data-id="${o.id}"`));}if(o.type==='model-detail'){const m=model(o.id);return modal('模型详情 · '+esc(m.name),kv('模型类型',modules[m.module].name)+kv('输入',m.inputs)+kv('格式 / 大小',m.format+' / '+m.size)+kv('训练类型',m.methods.map(k=>methodNames[k]).join('、'))+kv('更新方式',m.adapt.map(k=>adaptNames[k]).join('、'))+kv('运行组件',m.runtime)+kv('接入状态','交互演示，尚未验证真实适配')+(m.runtimeOnly?'<div class="nl-note">这是运行产物。再次训练请选择源模型。</div>':'')+(m.candidate?kv('来源实验',m.experiment):''),btn('运行模型','try-model',true,`data-id="${m.id}" ${!m.ready?'disabled':''}`)+btn('用于训练','train-model',false,`data-id="${m.id}" ${!m.ready||m.runtimeOnly?'disabled':''}`)+(m.candidate?btn('来源实验','model-source',false,`data-id="${m.experiment}"`):''));}if(o.type==='create')return modal('新建专项实验',`<div class="nl-create-grid">${Object.entries(expTypes).filter(([k])=>k!=='train').map(([k,n])=>`<button class="nl-template" data-create-type="${k}"><strong>${n}</strong><small>${k==='convert'?'转换模型格式，检查输出一致性':'保留输入、配置和独立候选'}</small></button>`).join('')}</div>`);if(o.type==='data')return modal('选择训练数据',`<small>当前要求：${schemaInfo[schemaFor(e)].name}</small><div class="nl-resource-list">${store.datasets.filter(d=>d.schema===schemaFor(e)).map(d=>`<div class="nl-resource-row"><div><strong>${esc(d.name)}</strong><small>${d.count} 条 · ${d.version} · ${d.ready?'已下载':'尚未下载'}</small></div>${d.ready?btn('选择','choose-data',true,`data-id="${d.id}"`):btn(downloadJob(d.id,'dataset')?'下载中':'下载','download-data',false,`data-id="${d.id}" ${downloadJob(d.id,'dataset')?'disabled':''}`)}</div>`).join('')}</div>`,btn('导入自己的数据','import-data')+btn('浏览市场','browse-market'));if(o.type==='reference')return modal(draft().kind==='audio'||draft().mode==='audio'?'选择录音':'选择参考素材',`<div class="nl-ref-option">${draft().kind==='audio'||draft().mode==='audio'?audio():art(draft().mode==='video'?'视频关键帧 · 演示素材':'商品参考素材')}<strong>${draft().kind==='audio'?'合成录音 · 内置样例':'商品参考图 · 内置样例'}</strong><small>可试听或预览后带入当前流程。</small></div>`,btn('使用此素材','use-reference',true));if(o.type==='recipe'){const r=resultById(o.id);return modal('结果配方',kv('结果',r.id)+(r.recipe.runtime?kv('运行引擎',runtimeEngines[r.recipe.runtime.engine])+kv('硬件后端',acceleratorNames[r.recipe.runtime.accelerator])+kv('配置来源','本次提交时固定的运行设置'):'')+kv('模型',esc(model(r.model)?.name))+`<label class="nl-field">输入与参数<textarea class="nl-json" readonly>${esc(JSON.stringify(r.recipe,null,2))}</textarea></label>`,btn('选中内容','select-recipe')+btn('载入配方继续修改','reuse',true,`data-id="${r.id}"`));}if(o.type==='import')return modal('导入数据',`<div class="nl-fields">${field('数据名称','name',o.name,'import')}${select('数据格式','schema',o.schema,Object.entries(schemaInfo).map(([k,v])=>[k,v.name]),'import')}${field('来源记录','source',o.source,'import')}<label class="nl-field">使用范围 · 用户声明<textarea data-import-field="statement">${esc(o.statement)}</textarea></label><div class="nu-panel-heading"><strong>粘贴 JSONL 内容</strong>${plain('载入格式样例','load-data-sample')}</div><textarea class="nl-json" data-import-field="content" aria-label="JSONL 内容">${esc(o.content)}</textarea><small>只保存在当前原型会话中；导入不代表平台确认来源或授权。</small>${o.error?`<div class="nl-error" role="alert">${esc(o.error)}</div>`:''}</div>`,btn('导入并保留','finish-import',true));if(o.type==='import-model')return modal('导入模型配置',`<div class="nl-fields">${field('模型名称','name',o.name,'import')}${select('模型类别','module',o.module,Object.entries(modules).map(([k,m])=>[k,m.name]),'import')}${field('权重路径或仓库标识','path',o.path,'import')}<small>演示只登记标识和同类模板，不读取文件或下载真实权重。</small>${o.error?`<div class="nl-error" role="alert">${esc(o.error)}</div>`:''}</div>`,btn('登记演示模型','finish-model-import',true));if(o.type==='preflight')return modal('确认启动本次任务',kv('任务',esc(e.name))+kv('模型',esc(model(e.model).name))+kv('类型',e.type==='train'?methodNames[e.method]:expTypes[e.type])+kv('更新方式',adaptNames[e.adapt])+kv('数据 / 划分',esc(dataFor(e).name)+' / 验证 '+e.split+'%')+kv('设备',store.settings.devices[e.device].name)+kv('使用范围声明',esc(e.sourceStatement||'用户未填写'))+'<small>本次演示将固定配置，开始模拟执行。AI 不会替你启动。</small>',btn('返回修改','close-overlay')+btn('启动演示','start-exp',true));if(o.type==='cancel')return modal('取消本次任务？','<p>停止当前演示，保留输入、配置和已完成结果。</p>',btn('保留任务','close-overlay')+btn('确认取消','confirm-cancel',true,`data-id="${o.id}"`));return '';}
function aiAdvice(){const d=currentExp();if(!store.settings.aiReady)return {title:'先连接 AI 助手',text:'可以在 AI 连接中选择本地或远程服务。当前建议为演示内容。'};if(store.page==='module'&&store.mode==='trial')return {title:'围绕当前输入给建议',text:'可以补充目标、约束与预期输出。先查看修改内容，再决定是否应用。',action:'prompt'};if(d&&(store.page==='lab'||store.mode==='train'&&store.page==='module')){if(d.status==='failed')return {title:'解释显存不足',text:'批量、序列长度和分辨率都可能影响显存。可复制配置为新尝试，再调整参数；原失败记录保留。'};if(['running','paused'].includes(d.status))return {title:'关注运行状态',text:'当前 '+d.progress+'% 是模拟进度。AI 可以解释日志；暂停、恢复和重启都由你操作。'};if(d.tab==='eval')return {title:'比较效果与回归',text:'先看验证样例，再检查能力、格式和目标效果。是否登记候选由你决定；当前评测数据是预置示例。'};if(d.step===1)return {title:d.dataIssues?.missing?'发现缺失字段':'先核对数据结构',text:d.dataIssues?.missing?'技术检查发现 2 条记录缺少必需字段。可以在任务副本中排除，然后重新检查。':'当前需要 '+schemaInfo[schemaFor(d)].name+'。可以检查必需字段和数据重叠；我不判断授权与合法性。',action:d.dataIssues?.missing?'data':null};if(d.step===0)return {title:'训练类型与更新方式分开选',text:'SFT 等训练类型决定数据与目标；LoRA 等方式决定更新哪些参数。当前选择 '+(d.type==='train'?methodNames[d.method]+' + '+adaptNames[d.adapt]:expTypes[d.type])+'。'};return {title:'先做小规模验证',text:'建议先减少步数和批量，确认数据、运行和产物流程，再扩大实验。建议不会自动生效。',action:'parameters'};}if(store.page==='data')return {title:'区分数据结构与来源声明',text:'我可以说明格式、查看缺失字段和重复样本。来源、许可和使用范围由你核对和填写，我不会作授权判定。'};return {title:'按当前目标提供辅助',text:'选择一类模型进入流程后，我会结合当前模型、方法、数据和运行状态给建议。所有修改都需要你点击应用。'};}
function changeLabel(key,value){if(key==='excluded')return value?'排除缺失记录':'保留全部记录';if(key==='dataChecked')return value?'检查已完成':'需要重新检查';return String(value);}
function aiPanel(){if(!store.ai.open)return '';const a=aiAdvice(),p=store.ai.proposal,labels={steps:'训练步数',batch:'每设备批量',budget:'候选预算',prompt:'输入内容',excluded:'排除缺失记录',dataChecked:'重新进行技术检查'};return `<div class="nu-ai-panel"><div class="nu-panel-heading"><h2>${icon('sparkles')} AI 辅助</h2>${plain(icon('panel-right-close'),'toggle-ai','aria-label="收起 AI 辅助"')}</div><span class="nu-ai-mode">建议模式 · 由你决定</span><div class="nu-ai-context"><strong>${a.title}</strong><p>${esc(a.text)}</p>${a.action&&!p?btn('查看具体建议','ai-propose',false,`data-proposal="${a.action}"`):''}</div>${p?`<div class="nu-proposal"><strong>${esc(p.title)}</strong><small>仅修改以下内容</small>${Object.entries(p.changes).map(([key,v])=>`<div class="nu-change"><span>${labels[key]||key}</span><del>${esc(changeLabel(key,v.from))}</del><strong>${esc(changeLabel(key,v.to))}</strong></div>`).join('')}<div class="nl-actions">${btn('应用这些修改','ai-apply',true)}${plain('放弃','ai-dismiss')}</div></div>`:''}${store.ai.undo&&((store.ai.undo.target==='exp'&&proposalTarget(store.ai.undo)?.status==='draft')||(store.ai.undo.target==='trial'&&!proposalTarget(store.ai.undo)?.running))?btn('撤销上次应用','ai-undo'):''}<div class="nu-ai-chat"><label class="nl-field">询问当前流程<textarea data-ai-question placeholder="例如：SFT 和 LoRA 怎么组合？">${esc(store.ai.question)}</textarea></label>${btn('发送问题','ask-ai')}<div class="nu-ai-answer" role="status">${esc(store.ai.answer)}</div></div><small>预置建议演示。不自动修改、执行或判定数据授权。</small>${plain('AI 连接设置','ai-settings')}</div>`;}
function syncAI(){if(store.ai.context!==aiContext()){store.ai.context=aiContext();store.ai.proposal=null;store.ai.undo=null;store.ai.answer='';}aiHost.innerHTML=aiPanel();root.querySelector('.nu-body').classList.toggle('with-ai',store.ai.open);root.querySelector('[data-action="toggle-ai"]').setAttribute('aria-pressed',String(store.ai.open));if(globalThis.lucide)lucide.createIcons({attrs:{width:16,height:16}});}
function updateChrome(){const page=store.page==='module'?'home':store.page;root.querySelectorAll('[data-nav]').forEach(b=>{if(b.dataset.nav===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});root.querySelector('[data-project]').value=store.project;const active=store.jobs.filter(j=>['running','paused'].includes(j.status)).length;root.querySelector('.nl-queue-label').textContent='任务队列'+(active?' · '+active:'');root.querySelector('.nl-toast').textContent=store.toast;}
function render(){main.innerHTML=store.page==='home'?homeScreen():store.page==='module'?moduleScreen():store.page==='lab'?labScreen():store.page==='models'?modelsScreen():store.page==='data'?dataScreen():assetsScreen();overlayHost.innerHTML=overlay();updateChrome();syncAI();applyVideoFrame();if(globalThis.lucide)lucide.createIcons({attrs:{width:16,height:16}});}
function openOverlay(value){store.overlay=value;media.playing=false;overlayHost.innerHTML=overlay();if(globalThis.lucide)lucide.createIcons({attrs:{width:16,height:16}});root.querySelector('.nl-dialog-head button')?.focus();}
function showToast(message){store.toast=message;root.querySelector('.nl-toast').textContent=message;}
function applyVideoFrame(){const r=trialResult(),seconds=Number(r?.recipe.seconds||5);const img=root.querySelector('.nl-art.video img');if(img)img.style.transform=`scale(${1+media.frame*.001}) translateX(${-media.frame*.025}%)`;const range=root.querySelector('[data-video-position]');if(range)range.value=media.frame;const time=root.querySelector('.nl-video-time');if(time)time.textContent=(media.frame/100*seconds).toFixed(1)+' / '+seconds.toFixed(1)+' 秒';}
function captureOrigin(){const e=currentExp();if(store.page==='module'||store.page==='lab'&&e)store.origin={page:store.page,module:store.module,mode:store.mode,project:store.project,exp:e?.id,name:e?.name||modules[store.module].name+'运行'};}
function returnOrigin(){const o=store.origin;if(!o)return;store.project=o.project;store.page=o.page;store.module=o.module;store.mode=o.mode;if(o.exp)store.selectedExp[o.page==='lab'?'lab|'+o.project:getTrainingKey(o.module)]=o.exp;store.origin=null;store.overlay=null;render();}
function routeToExperiment(id){const d=chosenExp(id);if(!d)return;selectProject(d.project);store.module=d.module;store.page=d.type==='train'?'module':'lab';store.mode='train';store.selectedExp[d.type==='train'?getTrainingKey(d.module):'lab|'+d.project]=d.id;store.overlay=null;render();}
function openModelForTrial(id){const m=model(id);if(!m?.ready)return;const key=store.project+'|'+m.kind;if(store.drafts[key]?.running){showToast('该类任务仍在执行，请先查看当前任务。');return;}store.page='module';store.mode='trial';setKind(m.kind);if(m.kind==='audio'&&m.op)operation(m.op);draft().model=id;store.overlay=null;store.origin=null;render();}
function workflowBanner(){const w=store.workflow;if(!w)return '';const definition=store.workflows.find(x=>x.id===w.id);return `<div class="nu-workflow-banner"><div><strong>${definition.name}</strong><small>第 ${w.stage+1} 步 · ${definition.nodes[w.stage]}</small></div><div class="nl-actions">${btn(w.stage===definition.models.length-1?'保存工作流结果':'带入下一步','workflow-next',true)}${plain('退出工作流','exit-workflow')}</div></div>`;}
function startWorkflow(id){const w=store.workflows.find(x=>x.id===id);if(w.models.some(x=>!model(x).ready))return;const m=model(w.models[0]);if(store.drafts[store.project+'|'+m.kind]?.running){showToast('本类别仍有运行任务，请先处理当前任务。');return;}store.workflow={id,stage:0,outputs:[],project:store.project};openModelForTrial(w.models[0]);draft().selected=null;if(w.id==='wf-inspect'){draft().reference=false;draft().mode='json';}render();}
function nextWorkflow(){const w=store.workflow,def=store.workflows.find(x=>x.id===w.id),r=trialResult();if(!r||r.recipe.workflow!==w.id||r.recipe.model!==def.models[w.stage]){showToast('请先完成当前步骤的一次生成，再继续。');return;}w.outputs.push({id:r.id,kind:r.kind});if(w.stage===def.models.length-1){for(const item of w.outputs){const x=resultById(item.id);if(x)x.favorite=true;}store.completedWorkflows??=[];store.completedWorkflows.push(clone(w));store.workflow=null;store.page='assets';store.assetTab='works';render();showToast('工作流结果已保存，各步骤的来源与配方保留。');return;}w.stage++;const m=model(def.models[w.stage]);openModelForTrial(m.id);if(m.kind==='video'){draft().reference=true;draft().source={id:r.id,name:r.id};}draft().selected=null;render();}
function handleAction(action,b){const d=draft(),e=currentExp();store.toast='';if(runtimeHandle(action,b))return;
if(action==='home'){store.page='home';store.origin=null;store.overlay=null;render();return;}
if(['models','market','lab'].includes(action)){store.page=action==='market'?'data':action;store.overlay=null;store.origin=null;if(action==='lab')store.selectedExp['lab|'+store.project]=null;render();return;}
if(action==='settings'||action==='ai-settings'){openOverlay({type:'settings',tab:action==='ai-settings'?'ai':'devices'});return;}
if(action==='toggle-ai'){store.ai.open=!store.ai.open;syncAI();return;}
if(action==='ai-propose'||action==='suggest-parameters'||action==='polish'){store.ai.open=true;store.ai.proposal=makeProposal(action==='polish'?'prompt':b.dataset.proposal||'parameters');syncAI();if(!store.ai.proposal)showToast('当前没有需要应用的参数调整，配置保持原样。');return;}
if(action==='ai-apply'){const ok=applyProposal();render();showToast(ok?'仅已列出的修改已应用，可撤销。':'配置已变化或任务已提交，请重新查看建议。');return;}
if(action==='ai-undo'||action==='undo-polish'){const ok=undoProposal();render();showToast(ok?'已撤销上次 AI 应用。':'配置已有后续修改或已提交，未覆盖你的操作。');return;}
if(action==='ai-dismiss'){store.ai.proposal=null;syncAI();return;}
if(action==='ask-ai'){store.ai.answer=answerAI(store.ai.question);syncAI();return;}
if(action==='queue'){openOverlay({type:'queue'});return;}
if(action==='close-overlay'){store.overlay=null;overlayHost.innerHTML='';return;}
if(action==='new-training'){newExperiment('train',store.module);store.ai.open=true;render();return;}
if(action==='config-back'){e.step=Math.max(0,e.step-1);e.error='';render();return;}
if(action==='config-next'){const error=validateExperiment(e,e.step);if(error){e.error=error.message;e.step=error.step;}else{e.step++;e.error='';}render();return;}
if(action==='pick-model'){if(b.dataset.target==='trial'&&d.running)return;openOverlay({type:'models',target:b.dataset.target});return;}
if(action==='choose-model'){if(store.overlay.target==='trial'){if(d.running)return;d.model=b.dataset.id;d.error='';}else chooseTrainingModel(e,b.dataset.id);store.overlay=null;render();return;}
if(action==='pick-data'){openOverlay({type:'data'});return;}
if(action==='choose-data'){if(chooseDataset(e,b.dataset.id)){store.overlay=null;render();}return;}
if(action==='browse-market'){captureOrigin();store.page='data';store.marketFilter='all';store.overlay=null;render();return;}
if(action==='return-origin'){returnOrigin();return;}
if(action==='check-data'){checkData(e);render();return;}
if(action==='exclude-missing'){e.excluded=true;e.dataChecked=false;e.dataIssues=null;render();showToast('只在本次任务副本中排除缺失记录，请重新检查。');return;}
if(action==='dedup-data'){e.deduped=true;e.dataChecked=false;e.dataIssues=null;render();showToast('只在本次任务副本中去重，请重新检查。');return;}
if(action==='data-detail'){const data=store.datasets.find(x=>x.id===b.dataset.id);openOverlay({type:'data-detail',id:data.id,source:data.source,statement:data.statement==='未填写'?'':data.statement});return;}
if(action==='save-statement'){const o=store.overlay,data=store.datasets.find(x=>x.id===o.id);data.source=o.source??data.source;data.statement=o.statement?.trim()||'未填写';if(e?.status==='draft'&&e.dataset===data.id)e.sourceStatement=data.statement==='未填写'?'':data.statement;showToast('已保存用户声明，未进行授权或合法性判定。');return;}
if(action==='download-data'){const data=store.datasets.find(x=>x.id===b.dataset.id);if(data.access==='request'&&data.accessStatus!=='granted'){openOverlay({type:'access',id:data.id,purpose:data.requestPurpose||'',error:''});return;}if(downloadJob(b.dataset.id,'dataset')){openOverlay({type:'queue'});return;}downloadDataset(b.dataset.id);render();return;}
if(action==='download-model'){if(downloadJob(b.dataset.id)){openOverlay({type:'queue'});return;}downloadModel(b.dataset.id);render();return;}
if(action==='send-access'){const data=store.datasets.find(x=>x.id===store.overlay.id);if(!store.overlay.purpose.trim()){store.overlay.error='填写访问用途，供提供方处理申请。';overlayHost.innerHTML=overlay();return;}data.requestPurpose=store.overlay.purpose;data.accessStatus='pending';overlayHost.innerHTML=overlay();return;}
if(action==='access-grant'||action==='access-reject'){const data=store.datasets.find(x=>x.id===store.overlay.id);data.accessStatus=action==='access-grant'?'granted':'rejected';overlayHost.innerHTML=overlay();return;}
if(action==='train-data'){const data=store.datasets.find(x=>x.id===b.dataset.id);if(!data?.ready)return;const original=store.origin?chosenExp(store.origin.exp):((store.page==='module'&&store.mode==='train'||store.page==='lab')&&e?.status==='draft'?e:null);if(original){if(data.schema!==schemaFor(original)){showToast('数据格式与原任务不匹配，请选择 '+schemaInfo[schemaFor(original)].name+'。');return;}chooseDataset(original,data.id);original.step=1;if(store.origin)returnOrigin();else{store.overlay=null;render();}return;}const module=data.kind==='text'||data.kind==='vision'?'language':data.kind;const targetModel=data.kind==='audio'?({tts:'cosy',asr:'whisper',vc:'rvc',music:'music'})[data.schema]:data.schema==='paired'?'fusion':templateModels[data.kind];const n=newExperiment('train',module,targetModel);if(data.kind==='text')n.method=data.schema;if(data.schema==='vision-dpo')n.method='dpo';chooseDataset(n,data.id);n.step=1;render();return;}
if(action==='import-data'){if(store.page==='module'||store.page==='lab')captureOrigin();openOverlay({type:'import',name:'我的训练数据',schema:e?schemaFor(e):'sft',source:'',statement:'',content:'',error:''});return;}
if(action==='load-data-sample'){store.overlay.content=schemaInfo[store.overlay.schema].sample;overlayHost.innerHTML=overlay();return;}
if(action==='finish-import'){const o=store.overlay;let rows;try{rows=o.content.split('\n').filter(x=>x.trim()).map(x=>JSON.parse(x));if(!rows.length||rows.some(x=>!x||typeof x!=='object'||Array.isArray(x)))throw Error();}catch{o.error='请粘贴有效 JSONL：每行一个 JSON 对象。';overlayHost.innerHTML=overlay();return;}if(!o.name.trim()){o.error='填写数据名称。';overlayHost.innerHTML=overlay();return;}const base=store.datasets.find(x=>x.schema===o.schema);const data={...clone(base),id:'ds-user-'+store.next++,name:o.name.trim(),source:o.source||'用户未填写',provider:'用户导入',statement:o.statement?.trim()||'未填写',terms:'用户自行提供的数据，未作来源或授权判定。',rows,count:rows.length,ready:true,version:'v1'};store.datasets.push(data);store.overlay=null;if(store.origin){const original=chosenExp(store.origin.exp);if(original&&schemaFor(original)===data.schema){chooseDataset(original,data.id);original.step=1;if(store.origin)returnOrigin();else{store.overlay=null;render();}return;}}store.page='data';store.marketTab='mine';store.marketFilter=data.kind;render();showToast('数据已导入。训练前可继续进行技术检查。');return;}
if(action==='preflight'){const error=validateExperiment(e);if(error){e.error=error.message;e.step=error.step;render();}else openOverlay({type:'preflight'});return;}
if(action==='start-exp'){store.overlay=null;submitExperiment();render();return;}
if(action==='open-exp'||action==='model-source'){const target=chosenExp(b.dataset.id);if(action==='open-exp'&&target.status==='complete')target.tab='eval';routeToExperiment(b.dataset.id);return;}
if(action==='tab-run'||action==='tab-eval'){e.tab=action==='tab-run'?'run':'eval';render();return;}
if(action==='pause-job'||action==='resume-job'){jobAction(b.dataset.id,action==='pause-job'?'pause':'resume');render();return;}
if(action==='cancel-job'){openOverlay({type:'cancel',id:b.dataset.id});return;}
if(action==='confirm-cancel'){jobAction(b.dataset.id,'cancel');store.overlay=null;render();return;}
if(action==='fail-exp'){failExperiment(e);render();return;}
if(action==='retry-exp'){retryExperiment(e);store.ai.proposal=null;render();return;}
if(action==='evaluate'||action==='eval-fail'){evaluateExperiment(e,action==='eval-fail');render();return;}
if(action==='register'){if(registerCandidate(e,Number(b.dataset.index))){render();showToast('候选已登记 · 演示，来源模型和任务配置已保留。');}return;}
if(action==='create'){openOverlay({type:'create'});return;}
if(action==='lab-list'){store.selectedExp['lab|'+store.project]=null;render();return;}
if(action==='try-candidate'||action==='try-model'){store.workflow=null;openModelForTrial(b.dataset.id);return;}
if(action==='train-model'){const m=model(b.dataset.id);if(!m.ready||m.runtimeOnly)return;newExperiment('train',m.module,m.id);store.ai.open=true;render();return;}
if(action==='model-detail'){openOverlay({type:'model-detail',id:b.dataset.id});return;}
if(action==='import-model'){openOverlay({type:'import-model',name:'我的模型',module:'language',path:'',error:''});return;}
if(action==='finish-model-import'){const o=store.overlay;if(!o.name.trim()||!o.path.trim()){o.error='填写模型名称与权重标识。';overlayHost.innerHTML=overlay();return;}const base=model(({language:'qwen4',image:'sdxl',video:'wan',audio:'cosy'})[o.module]);store.models.push({...clone(base),id:'custom-'+store.next++,name:o.name.trim(),source:o.path,ready:true,project:store.project});store.modelFilter=o.module;store.modelTab='models';store.overlay=null;render();showToast('已登记演示配置，真实文件与模型结构尚未读取。');return;}
if(action==='device-detail'){openOverlay({type:'device',id:b.dataset.id});return;}
if(action==='save-device'){showToast('已保留设备配置；可继续模拟连接检查。');return;}
if(action==='connect'){store.settings.devices[b.dataset.id].ready=true;overlayHost.innerHTML=overlay();showToast('模拟连接通过，可以返回原任务继续。');return;}
if(action==='connect-ai'){store.settings.aiReady=true;overlayHost.innerHTML=overlay();syncAI();return;}
if(action==='reference'){openOverlay({type:'reference'});return;}
if(action==='use-reference'){d.reference=true;d.error='';store.overlay=null;render();return;}
if(action==='generate'){submitTrial();render();return;}
if(action==='favorite'){const r=resultById(b.dataset.id);r.favorite=!r.favorite;render();return;}
if(action==='compare'){store.compare=!store.compare;render();return;}
if(action==='recipe'||action==='asset-recipe'){openOverlay({type:'recipe',id:b.dataset.id});return;}
if(action==='select-recipe'){root.querySelector('.nl-json')?.select();return;}
if(action==='reuse'){const r=resultById(b.dataset.id);if(r.kind!==store.kind)setKind(r.kind);store.page='module';store.mode='trial';if(reuseResult(r)){store.overlay=null;render();showToast('配方已回填，修改后可再次运行。');}else showToast('请先处理当前运行任务。');return;}
if(action==='to-video'){if(copyToVideo(resultById(b.dataset.id)))render();else showToast('视频任务仍在执行，请先处理当前任务。');return;}
if(action==='video-play'){if(media.frame>=100)media.frame=0;media.playing=!media.playing;render();return;}
if(action==='open-job'){const j=store.jobs.find(x=>x.id===b.dataset.id);if(j.type==='experiment'){routeToExperiment(j.id);return;}selectProject(j.project);setKind(j.kind);store.page='module';store.mode='trial';if(j.kind==='audio'&&draft().op!==j.snapshot.op)operation(j.snapshot.op);draft().selected=j.id;store.overlay=null;render();return;}
if(action==='open-asset'){const r=resultById(b.dataset.id);setKind(r.kind);store.page='module';store.mode='trial';if(r.kind==='audio')operation(r.op);draft().selected=r.id;render();return;}
if(action==='use-asset'){setKind(b.dataset.kind);store.page='module';store.mode='trial';if(store.kind==='audio')operation('asr');draft().reference=true;if(store.kind==='image')draft().mode='i2i';render();return;}
if(action==='workflow-detail'){openOverlay({type:'workflow',id:b.dataset.id});return;}
if(action==='start-workflow'){startWorkflow(b.dataset.id);return;}
if(action==='workflow-next'){nextWorkflow();return;}
if(action==='exit-workflow'){store.workflow=null;render();return;}
}
root.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||!root.contains(b)||b.disabled)return;if(b.dataset.action!=='video-play')media.playing=false;
if(b.dataset.nav){store.page=b.dataset.nav;store.overlay=null;store.origin=null;store.toast='';store.workflow=null;render();return;}
if(b.dataset.enterModule){enterModule(b.dataset.enterModule);store.ai.open=true;render();return;}
if(b.dataset.moduleMode){store.mode=b.dataset.moduleMode;store.ai.proposal=null;if(store.mode==='train'&&!currentExp())newExperiment('train',store.module);if(store.mode==='trial'&&!((store.module==='language'&&['text','vision'].includes(store.kind))||store.kind===store.module))setKind(store.module==='language'?'text':store.module);render();return;}
if(b.dataset.kind&&!b.dataset.action){setKind(b.dataset.kind);render();return;}
if(b.dataset.result){draft().selected=b.dataset.result;media.frame=0;render();return;}
if(b.dataset.historyTab){store.trialTab=b.dataset.historyTab;render();return;}
if(b.dataset.expTab){currentExp().tab=b.dataset.expTab;render();return;}
if(b.dataset.configStep!==undefined){currentExp().step=Number(b.dataset.configStep);currentExp().error='';render();return;}
if(b.dataset.createType){newExperiment(b.dataset.createType,b.dataset.createType==='convert'?'image':'language',b.dataset.createType==='convert'?'fusion':undefined);store.ai.open=true;render();return;}
if(b.dataset.modelTab){store.modelTab=b.dataset.modelTab;render();return;}
if(b.dataset.marketTab){store.marketTab=b.dataset.marketTab;render();return;}
if(b.dataset.assetTab){store.assetTab=b.dataset.assetTab;render();return;}
if(b.dataset.settingsTab){openOverlay({type:'settings',tab:b.dataset.settingsTab});return;}
if(b.dataset.action)handleAction(b.dataset.action,b);
});
root.addEventListener('input',event=>{const x=event.target;if(x.dataset.runtimeField&&store.overlay?.type==='runtime'&&x.tagName!=='SELECT'&&x.type!=='checkbox'){store.overlay.config[x.dataset.runtimeField]=x.value;store.overlay.errors=[];return;}if(x.dataset.trialField&&x.tagName!=='SELECT'&&x.type!=='checkbox'&&!draft().running){draft()[x.dataset.trialField]=x.value;draft().error='';}if(x.dataset.expField&&currentExp()?.status==='draft'&&x.tagName!=='SELECT'&&x.type!=='checkbox'){currentExp()[x.dataset.expField]=x.value;currentExp().error='';if(x.dataset.expField==='split')currentExp().dataChecked=false;}if(x.dataset.importField&&store.overlay)x.type!=='checkbox'&&(store.overlay[x.dataset.importField]=x.value);if(x.dataset.datametaField&&store.overlay)store.overlay[x.dataset.datametaField]=x.value;if(x.dataset.dataMetaField&&store.overlay)store.overlay[x.dataset.dataMetaField]=x.value;if(x.dataset.dataMeta&&store.overlay)store.overlay[x.dataset.dataMeta]=x.value;if(x.dataset.settingsField){store.settings[x.dataset.settingsField]=x.value;if(x.dataset.settingsField!=='device')store.settings.aiReady=false;}if(x.dataset.deviceField&&store.overlay?.type==='device'){store.settings.devices[store.overlay.id][x.dataset.deviceField]=x.value;store.settings.devices[store.overlay.id].ready=false;}if(x.hasAttribute('data-access-purpose'))store.overlay.purpose=x.value;if(x.hasAttribute('data-ai-question'))store.ai.question=x.value;if(x.dataset.resultTranscript){const r=resultById(x.dataset.resultTranscript);if(r){r.transcript=x.value;r.recipe.transcript=x.value;}}if(x.hasAttribute('data-video-position')){media.frame=Number(x.value);media.playing=false;applyVideoFrame();}});
root.addEventListener('change',event=>{const x=event.target;if(x.dataset.runtimeField&&store.overlay?.type==='runtime'){const o=store.overlay;o.notice=runtimeChange(o.config,x.dataset.runtimeField,x.type==='checkbox'?x.checked:x.value,draft());o.errors=[];overlayHost.innerHTML=overlay();return;}if(x.hasAttribute('data-project')){selectProject(x.value);store.origin=null;if(store.page==='module'&&store.mode==='train'&&!currentExp())newExperiment('train',store.module);render();return;}if(x.hasAttribute('data-compare-id')){draft().compareId=x.value;render();return;}if(x.dataset.trialField&&(x.tagName==='SELECT'||x.type==='checkbox')){if(draft().running)return;const key=x.dataset.trialField;if(key==='op')operation(x.value);else draft()[key]=x.type==='checkbox'?x.checked:x.value;draft().error='';render();return;}if(x.dataset.expField&&(x.tagName==='SELECT'||x.type==='checkbox')&&currentExp()?.status==='draft'){changeMethod(currentExp(),x.dataset.expField,x.type==='checkbox'?x.checked:x.value);render();return;}if(x.dataset.viewField){store[x.dataset.viewField]=x.value;render();return;}if(x.dataset.settingsField){store.settings[x.dataset.settingsField]=x.value;if(x.dataset.settingsField!=='device')store.settings.aiReady=false;return;}if(x.dataset.importField){store.overlay[x.dataset.importField]=x.value;return;}if(x.dataset.deviceField){store.settings.devices[store.overlay.id][x.dataset.deviceField]=x.value;store.settings.devices[store.overlay.id].ready=false;return;}if(x.dataset.expField||x.dataset.trialField)syncAI();});
root.addEventListener('keydown',event=>{if(event.key==='Escape'&&store.overlay){store.overlay=null;overlayHost.innerHTML='';}});
let pendingJobRefresh=false;
function userEditing(){const x=document.activeElement;return x&&root.contains(x)&&['INPUT','TEXTAREA','SELECT'].includes(x.tagName)&&!x.readOnly;}
function refreshJobs(){if(userEditing()){pendingJobRefresh=true;updateChrome();}else{pendingJobRefresh=false;render();}}
root.addEventListener('focusout',()=>setTimeout(()=>{if(pendingJobRefresh&&!userEditing()){pendingJobRefresh=false;render();}},0));
const jobTimer=setInterval(()=>{if(!root.isConnected){clearInterval(jobTimer);return;}if(advanceJobs()){const e=currentExp(),busyTrial=store.page==='module'&&store.mode==='trial'&&!!draft().running;const finishedTrial=store.page==='module'&&store.mode==='trial'&&store.jobs.some(j=>j.type==='trial'&&j.project===store.project&&j.kind===store.kind&&j.progress===100&&!j.painted);store.jobs.filter(j=>j.progress===100).forEach(j=>j.painted=true);if((e&&e.tab==='run'&&['module','lab'].includes(store.page))||busyTrial||finishedTrial||['queue','models','data','workflow','data-detail','access'].includes(store.overlay?.type)||['models','data','home'].includes(store.page)||store.page==='module'&&store.mode==='history')refreshJobs();else updateChrome();}},900);
const videoTimer=setInterval(()=>{if(!root.isConnected){clearInterval(videoTimer);return;}if(media.playing&&store.page==='module'&&store.mode==='trial'&&store.kind==='video'){const seconds=Number(trialResult()?.recipe.seconds||5);media.frame=Math.min(100,media.frame+10/seconds);applyVideoFrame();if(media.frame>=100){media.playing=false;render();}}},100);
function applyDesign(){root.style.setProperty('--nl-radius',design.radius+'px');root.style.setProperty('--nl-accent',design.accent==='teal'?'light-dark(#187d72,#81d5c6)':'light-dark(#5148d8,#aa9dff)');root.style.setProperty('--nl-tint',design.accent==='teal'?'light-dark(#e6f5f0,#203d39)':'light-dark(#eeecff,#332d52)');}
applyDesign();render();
if(globalThis.Tweak){const tweak=new Tweak({container:root,onChange:applyDesign});tweak.addSelect(design,'accent',{label:'强调色',options:[{label:'靛蓝',value:'indigo'},{label:'青绿',value:'teal'}]});tweak.addSlider(design,'radius',{label:'面板圆角',min:6,max:18,step:2,unit:'px'});}
